29:     public void handle(RoutingContext routingContext) {
30:         if (!setup) {
31:             setup();
32:         }
33: 
34:         HttpServerResponse response = routingContext.response();
35:         if (registry == null) {
36:             response.setStatusCode(500)
37:                     .setStatusMessage("Unable to resolve Prometheus registry instance");
38:         } else {
39:             ManagedContext requestContext = Arc.container().requestContext();
40:             var acceptHeader = chooseContentType(routingContext.request().getHeader("Accept"));
41:             if (requestContext.isActive()) {
42:                 doHandle(response, acceptHeader);
43:             } else {
44:                 requestContext.activate();
45:                 try {
46:                     doHandle(response, acceptHeader);
47:                 } finally {
48:                     requestContext.terminate();
49:                 }
50:             }
51:         }
52:     }
53: 
54:     private String chooseContentType(String acceptHeader) {
55:         if (acceptHeader == null) {
56:             return CONTENT_TYPE_OPENMETRICS_100;
57:         }
58:         if (acceptHeader.contains("text/plain") || acceptHeader.contains("text/html")) {
59:             return CONTENT_TYPE_004;
60:         }
61:         return CONTENT_TYPE_OPENMETRICS_100;
62:     }
63: 
64:     private void doHandle(HttpServerResponse response, String acceptHeader) {
65:         response.putHeader("Content-Type", acceptHeader)
66:                 .end(Buffer.buffer(registry.scrape(acceptHeader)));
67:     }
68: 
69:     private void setup() {
70:         Instance<PrometheusMeterRegistry> registries = CDI.current().select(PrometheusMeterRegistry.class,
71:                 Default.Literal.INSTANCE);
72: 
73:         if (registries.isUnsatisfied()) {
74:             registry = null;
75:         } else if (registries.isAmbiguous()) {
76:             registry = registries.iterator().next();
77:             log.warnf("Multiple prometheus registries present. Using %s with the built-in scrape endpoint",
78:                     registry);
79:         } else {
80:             registry = registries.get();
81:         }
82: 
83:         setup = true;
84:     }
